-- 017_signatory_kimuli_payroll.sql
-- Payroll payments keep Dr. Kimuli Ismail as Managing Director signatory.
-- Signatories now carry a scope: "all" (statements, POs, reports) or
-- "payroll" (salary ledgers, bank reports, supplier payment schedules and
-- payment advice — which carry every signatory). Existing entries become
-- "all"; Dr. Kimuli Ismail is added with scope "payroll" and his signature
-- (unless a Kimuli entry already exists, in which case it is updated).
-- (With no stored list the built-in defaults already include him.)
-- Everything remains editable in Settings -> General -> Approved signatories.
UPDATE settings
SET value = jsonb_set(
      value,
      '{signatories}',
      (
        SELECT COALESCE(jsonb_agg(
          CASE
            WHEN s->>'name' ILIKE '%kimuli%' THEN s
              || jsonb_build_object('name', 'Dr. Kimuli Ismail', 'title', 'Managing Director', 'scope', 'payroll')
              || CASE WHEN COALESCE(s->>'signature', '') = '' THEN jsonb_build_object('signature', 'data:image/png;base64,') ELSE '{}'::jsonb END
              || CASE WHEN COALESCE(s->>'contact', '') = '' THEN jsonb_build_object('contact', '256701506063') ELSE '{}'::jsonb END
            WHEN COALESCE(s->>'scope', '') = '' THEN s || '{"scope":"all"}'::jsonb
            ELSE s
          END
        ), '[]'::jsonb)
        FROM jsonb_array_elements(
               CASE WHEN jsonb_typeof(value->'signatories') = 'array' THEN value->'signatories' ELSE '[]'::jsonb END
             ) AS s
      )
      || CASE
           WHEN EXISTS (
             SELECT 1 FROM jsonb_array_elements(
               CASE WHEN jsonb_typeof(value->'signatories') = 'array' THEN value->'signatories' ELSE '[]'::jsonb END
             ) AS k WHERE k->>'name' ILIKE '%kimuli%'
           ) THEN '[]'::jsonb
           ELSE jsonb_build_array(jsonb_build_object(
             'name', 'Dr. Kimuli Ismail', 'title', 'Managing Director', 'contact', '256701506063',
             'scope', 'payroll', 'signature', 'data:image/png;base64,'))
         END,
      true
    ),
    updated_at = now()
WHERE key = 'app'
  AND jsonb_typeof(value->'signatories') = 'array'
  AND jsonb_array_length(value->'signatories') > 0;
